"use client"

import * as React from "react"
import { ChevronRightIcon } from "lucide-react"
import { cn } from "cn"
import {
  Button,
  Link,
  Tree as TreePrimitive,
  TreeItem as TreeItemPrimitive,
  TreeItemContent,
  type TreeItemProps,
  type TreeProps,
} from "react-aria-components"

/**
 * Navigation tree: React Aria Tree (APG treeview) styled as the aria-nova
 * sidebar menu. Branches expand with the chevron or arrow keys; leaves are
 * links, and the current page carries aria-current="page".
 */
function NavigationTree<T extends object>({
  className,
  ...props
}: Omit<TreeProps<T>, "className"> & { className?: string }) {
  return (
    <TreePrimitive
      data-slot="navigation-tree"
      className={cn("flex w-full min-w-0 flex-col gap-0.5 text-sm text-sidebar-foreground outline-none", className)}
      {...props}
    />
  )
}

/** One node; nested NavigationTreeItem children make it a branch. */
function NavigationTreeItem({
  className,
  title,
  href,
  current = false,
  icon,
  children,
  textValue,
  ...props
}: Omit<TreeItemProps, "className" | "children" | "href"> & {
  className?: string
  title?: React.ReactNode
  href?: string
  current?: boolean
  icon?: React.ReactNode
  children?: React.ReactNode
}) {
  return (
    <TreeItemPrimitive
      data-slot="navigation-tree-item"
      data-current={current || undefined}
      textValue={textValue}
      className={cn(
        "group/navigation-tree-item rounded-md outline-none data-[disabled]:opacity-50 data-[focus-visible]:ring-2 data-[focus-visible]:ring-sidebar-ring",
        className
      )}
      {...props}
    >
      <TreeItemContent>
        {({ hasChildItems, isExpanded, level }) => (
          <div
            data-slot="navigation-tree-item-content"
            className={cn(
              "flex h-8 items-center gap-2 rounded-md pr-2 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
              current && "bg-sidebar-accent font-medium text-sidebar-accent-foreground"
            )}
            style={{ paddingInlineStart: `calc(${level - 1} * var(--spacing) * 4 + var(--spacing) * 1)` }}
          >
            {hasChildItems ? (
              <Button
                slot="chevron"
                data-slot="navigation-tree-expand"
                className="flex size-5 shrink-0 items-center justify-center rounded-sm text-sidebar-foreground/70 outline-none data-[focus-visible]:ring-2 data-[focus-visible]:ring-sidebar-ring"
              >
                <ChevronRightIcon className={cn("size-3.5 transition-transform rtl:rotate-180", isExpanded && "rotate-90 rtl:rotate-90")} />
              </Button>
            ) : (
              <span aria-hidden="true" className="size-5 shrink-0" />
            )}
            {icon && <span className="flex shrink-0 [&_svg:not([class*='size-'])]:size-4">{icon}</span>}
            {href ? (
              <Link
                href={href}
                aria-current={current ? "page" : undefined}
                className="min-w-0 flex-1 truncate outline-none"
              >
                {title ?? textValue}
              </Link>
            ) : (
              <span className="min-w-0 flex-1 truncate">{title ?? textValue}</span>
            )}
          </div>
        )}
      </TreeItemContent>
      {children}
    </TreeItemPrimitive>
  )
}

export { NavigationTree, NavigationTreeItem }
